// Staff registration: one form for every delegate and exhibitor category,
// confirmed on save as paid (verified bank payment) or complimentary. The
// draft survives re-renders when the category or payment choice changes.
let staffDraft=null,staffLogo=null;
const staffFields=['category_id','institution','contact_name','email','phone','description','payment','verified_reference','verified_date','amount','coupon_code','note'];
function optField(label,name,value='',type='text',extra=''){return `<label>${esc(label)}<input name="${esc(name)}" value="${esc(value)}" type="${type}" ${extra}></label>`;}
function staffCategory(){return config.categories.find(c=>c.id===staffDraft.category_id)||config.categories[0];}
function staffCapture(form){const f=new FormData(form),d=staffDraft;for(const k of staffFields)if(f.has(k))d[k]=String(f.get(k));d.attendees=d.attendees.map((p,i)=>f.has(`name_${i}`)?{name:String(f.get(`name_${i}`)),designation:String(f.get(`designation_${i}`)),email:String(f.get(`email_${i}`)),phone:String(f.get(`phone_${i}`)),whatsapp_consent:f.has(`whatsapp_${i}`)}:p);if(f.has('amount'))d.accept_amount=f.has('accept_amount');const logo=f.get('logo');if(logo?.size)staffLogo=logo;}
function staffAttendee(p,i,kind,either,guest){if(guest)return `<fieldset><legend>Guest</legend><div class="fields">${optField('Full name',`name_${i}`,p.name,'text','maxlength="120" required')}${optField('Designation (optional)',`designation_${i}`,p.designation,'text','maxlength="180"')}${optField('Email (optional)',`email_${i}`,p.email,'email')}${optField('Phone (optional, e.g. +919876543210)',`phone_${i}`,p.phone,'tel',phonePattern)}</div><p class="help">Only the name is required. The pass is never sent, even with an email or phone: it downloads when you confirm, and stays under Download pass on the registration.</p></fieldset>`;const need=i===0,req=need?'required':'';return `<fieldset><legend>${kind==='delegate'?'Attendee':`Attendee ${i+1}${i?' - optional':''}`}</legend><div class="fields">${optField('Full name',`name_${i}`,p.name,'text',`maxlength="120" ${req}`)}${optField('Designation',`designation_${i}`,p.designation,'text',`maxlength="180" ${req}`)}${either?eitherContactFields(p.email,p.phone,`email_${i}`,`phone_${i}`):`${optField('Email',`email_${i}`,p.email,'email',req)}${optField('Phone (optional, e.g. +919876543210)',`phone_${i}`,p.phone,'tel',phonePattern)}`}</div><label class="check"><input type="checkbox" name="whatsapp_${i}" ${p.whatsapp_consent?'checked':''}>Send this attendee's pass by WhatsApp too (needs a phone number).</label>${need?'':'<p class="help">Leave blank to fill this place later.</p>'}</fieldset>`;}
async function staffRegistrationPage(){await loadConfig();if(!staffDraft){staffDraft={category_id:'industry',institution:'',contact_name:'',email:'',phone:'',description:'',payment:'complimentary',verified_reference:'',verified_date:'',amount:'',coupon_code:'',note:'',attendees:[],key:uuid()};staffLogo=null;}const d=staffDraft,c=staffCategory(),kind=c.kind,guest=c.download_only,today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata'}).format(new Date());while(d.attendees.length<c.roster_count)d.attendees.push(person());d.attendees.length=c.roster_count;if(c.free_only)d.payment='complimentary';const paid=d.payment==='paid',group=k=>config.categories.filter(x=>x.kind===k).map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.label)}${x.free_only?' - complimentary only':''}</option>`).join('');
app.innerHTML=`<button id="return" class="secondary back-button"><span aria-hidden="true">&larr;</span> Back to registrations</button><h1>New registration.</h1><p>Register a delegate or exhibitor on their behalf. The registration is confirmed when you save it, whether or not public registration or the category is open. Nothing is emailed unless you choose to send the passes.</p><form id="staff-registration" class="card"><h2>Details</h2><div class="fields"><label class="full">Category<select name="category_id" id="staff-category"><optgroup label="Delegates">${group('delegate')}</optgroup><optgroup label="Exhibitors">${group('exhibitor')}</optgroup></select></label><label class="full">Institution${guest?' (optional)':''}<input name="institution" value="${esc(d.institution)}" maxlength="180" autocomplete="organization" ${guest?'':'required'}></label>${kind==='exhibitor'?`${field('Contact person','contact_name',d.contact_name,'text','maxlength="120"')}${field('Contact email','email',d.email,'email')}${optField('Contact phone (optional, +country code)','phone',d.phone,'tel','pattern="\\+[1-9][0-9]{7,14}"')}<label class="full">Company description<textarea name="description" required maxlength="3000">${esc(d.description)}</textarea></label><label class="full">Institution logo (optional, PNG or JPEG up to 5 MB)<input type="file" name="logo" accept="image/png,image/jpeg"></label>${staffLogo?`<p class="help full">Selected: ${esc(staffLogo.name)} - choose a file again only to replace it.</p>`:''}`:''}</div>
<h3>${kind==='delegate'?'Pass holder':'Attendees'}</h3>${kind==='exhibitor'?`<p class="help">This stall includes ${c.roster_count} ${c.roster_count===1?'pass':'passes'}. Add at least one attendee; the rest can be added later from the registration.</p>`:''}${d.attendees.map((p,i)=>staffAttendee(p,i,kind,emailOptional(c.id),guest)).join('')}
<h3>Payment</h3><div class="fields"><label class="check"><input type="radio" name="payment" value="complimentary" ${paid?'':'checked'}>Complimentary</label><label class="check"><input type="radio" name="payment" value="paid" ${paid?'checked':''} ${c.free_only?'disabled':''}>Paid - verified bank payment</label></div>${paid?`<p class="help">Enter the transaction as it appears in the bank's reconciliation report. The amount should equal the fee for the payment date${c.coupon_eligible?', less any coupon':''}. Fee for a payment made today: ${money(c.payable_paise)}.</p><div class="fields">${field('Verified bank reference','verified_reference',d.verified_reference,'text','maxlength="100"')}${field('Verified payment date','verified_date',d.verified_date||today,'date',`max="${today}"`)}${field('Verified amount in INR','amount',d.amount||(c.payable_paise/100).toFixed(2),'number','min="0.01" step="0.01"')}${c.coupon_eligible?optField('Coupon code (optional)','coupon_code',d.coupon_code,'text','maxlength="40" autocomplete="off"'):''}</div>${amountAccept(c.payable_paise,d.accept_amount)}<label class="check"><input type="checkbox" name="successful" required>I verified the transaction succeeded.</label><label class="check"><input type="checkbox" name="beneficiary_confirmed" required>I verified the correct beneficiary.</label>`:`<p class="help">${c.free_only?'This category is complimentary only. ':''}No payment is recorded.</p>`}
<label>Organiser note (optional)<textarea name="note" maxlength="2000">${esc(d.note)}</textarea></label>${guest?'<div class="actions"><button value="confirm">Confirm and download pass</button></div>':'<div class="actions"><button value="send">Confirm and send passes</button><button value="confirm" class="secondary">Confirm only</button></div><p class="help">Confirm only issues the passes without sending them; send them from the registration when ready.</p>'}</form>`;
window.scrollTo({top:0});const form=document.getElementById('staff-registration');
form.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.tagName==='INPUT')e.preventDefault();});
bind('return','click',()=>{staffDraft=null;staffLogo=null;return adminList();});
form.addEventListener('change',e=>{if(e.target.name==='category_id'||e.target.name==='payment'){staffCapture(form);staffRegistrationPage().catch(err=>message(err.message,true));}});
bind('staff-registration','submit',async e=>{e.preventDefault();staffCapture(form);const c=staffCategory(),d=staffDraft,people=d.attendees.filter((p,i)=>i===0||p.name.trim()||p.email.trim()||p.designation.trim()||p.phone.trim()),missing=emailOptional(c.id)&&contactMissing(people);if(missing)throw Error(missing);const first=people[0],body={category_id:c.id,institution:d.institution,contact_name:c.kind==='delegate'?first.name:d.contact_name,email:c.kind==='delegate'?first.email:d.email,phone:c.kind==='delegate'?first.phone:d.phone,description:c.kind==='exhibitor'?d.description:'',coupon_code:d.payment==='paid'?d.coupon_code:'',attendees:people,payment:d.payment,send:e.submitter?.value==='send',note:d.note};if(d.payment==='paid')Object.assign(body,{verified_reference:d.verified_reference,verified_date:d.verified_date,verified_amount_paise:paise(d.amount),accept_amount:!!d.accept_amount});await busy(e.submitter,async()=>{const fd=new FormData();fd.append('payload',JSON.stringify(body));if(c.kind==='exhibitor'&&staffLogo)fd.append('logo',staffLogo);let res;try{res=await fetch('/api/v1/admin/registrations',{method:'POST',headers:{'Idempotency-Key':d.key,'X-CSRF-Token':csrf()},body:fd});}catch{throw Error('Network error. Check your connection and retry.');}await checkStaffResponse(res,'/admin/registrations');const out=await res.json().catch(()=>null);if(!res.ok)throw Error(out?.error||`Request failed (${res.status}). Please retry.`);staffDraft=null;staffLogo=null;if(c.download_only){const pass=(await api('/admin/registrations/'+out.id)).passes.find(p=>!p.revoked_at);await adminDetail(out.id,{push:true});message('Guest registered. The pass is downloading now; it is also under Download pass below.');if(pass)location.assign(`/api/v1/admin/registrations/${out.id}/passes/${pass.id}.pdf`);return;}await adminDetail(out.id,{push:true});message(body.send?'Registration confirmed. Passes are being sent.':'Registration confirmed. Passes are issued but not sent.');});});}
// Speakers: collect each speaker's email, issue their complimentary pass, then
// send it. Each step is separate and explicit; sending reuses the registration
// review actions.
let speakerRows=[],speakerTab='',speakerQuery='';
const speakerTabs=[['','All'],['email','Needs email'],['saved','Email saved'],['print','Download only'],['ready','Not sent'],['sent','Sent'],['failed','Failed']];
// A pass goes by email, and by WhatsApp when the holder has a phone and
// consent. It counts as sent once any channel is under way, and as failed
// only when every channel tried has failed.
function speakerJobs(s){return [s.delivery?.status,s.whatsapp?.status].filter(d=>d&&d!=='cancelled');}
function speakerState(s){if(!s.pass||s.registration?.status!=='approved')return s.contact?'saved':'email';const h=s.attendee;if(!h?.email&&!(h?.phone&&h?.whatsapp_consent))return 'print';const jobs=speakerJobs(s);if(!jobs.length)return 'ready';return jobs.every(d=>['failed','uncertain'].includes(d))?'failed':'sent';}
const deliveryName=d=>({queued:'Sending',sending:'Sending',accepted:'Sent',delivered:'Delivered',failed:'Failed',uncertain:'Check',cancelled:'Cancelled'})[d]||d;
function speakerStatus(s){const st=speakerState(s),d=s.delivery;if(st==='email')return ['Needs email','muted'];if(st==='saved')return s.registration?.status==='cancelled'?['Pass cancelled','cancelled']:['No pass yet','saved'];if(st==='print')return ['Download only','saved'];if(st==='ready')return ['Not sent','pending'];const jobs=speakerJobs(s);if(st==='failed')return [jobs.includes('uncertain')?'Check delivery':'Failed','failed'];return [jobs.includes('delivered')?'Delivered':jobs.includes('accepted')?'Sent':'Sending','sent'];}
function initials(name){return String(name).replace(/^(dr|prof|mr|mrs|ms|shri|smt)\.?\s+/i,'').split(/\s+/).filter(w=>/^[A-Za-z]/.test(w)).map(w=>w[0]).slice(0,2).join('').toUpperCase()||'?';}
function speakerContact(s){return s.pass&&s.registration?.status==='approved'?s.attendee:s.contact;}
function speakerRow(s){const st=speakerState(s),[label,tone]=speakerStatus(s),a=speakerContact(s),r=s.registration,when=[['Email',s.delivery],['WhatsApp',s.whatsapp]].filter(([,d])=>d).map(([n,d])=>`<small>${n}: ${esc(deliveryName(d.status))}</small>`).join(''),wa=a?(a.whatsapp_consent||!s.contact&&!s.pass):true;return `<li class="speaker-row" data-id="${esc(s.id)}"><span class="speaker-avatar" aria-hidden="true"${s.image_url?` data-src="${esc(s.image_url)}"`:''}>${esc(initials(s.name))}</span><div class="speaker-who"><strong>${esc(s.name)}</strong><span>${esc([s.role,s.organization].filter(Boolean).join(' · '))}</span>${s.published?'':'<span class="speaker-flag">Hidden in app</span>'}</div><form class="speaker-contact" data-id="${esc(s.id)}" novalidate><label><span class="sr-only">Email for ${esc(s.name)}</span><input name="email" type="email" value="${esc(a?.email||'')}" placeholder="Email address" autocomplete="off" spellcheck="false"></label><label><span class="sr-only">Phone for ${esc(s.name)} (optional)</span><input name="phone" type="tel" value="${esc(a?.phone||'')}" placeholder="Phone (optional)" autocomplete="off" pattern="\+[1-9][0-9]{7,14}"></label><label class="speaker-wa" title="Also send the pass by WhatsApp"><input type="checkbox" name="whatsapp" ${wa?'checked':''} ${a?.phone?'':'disabled'}>WhatsApp</label><button class="speaker-save${a?' secondary':''}" hidden>Save</button></form><div class="speaker-state"><span class="speaker-pill speaker-pill-${tone}">${esc(label)}</span>${when}</div><div class="speaker-actions">${st==='saved'?`<button type="button" class="speaker-issue">Issue pass</button>`:''}${st==='email'?`<button type="button" class="secondary speaker-print" title="For a speaker with no email or phone: issue the pass to download and hand over">Pass for download</button>`:''}${st==='ready'?`<button type="button" class="speaker-send" data-action="send">Send pass</button>`:''}${st==='sent'||st==='failed'?`<button type="button" class="secondary speaker-send" data-action="resend">Resend</button>`:''}${s.pass&&['print','ready','sent','failed'].includes(st)?`<a class="button${st==='print'?'':' quiet'}" href="/api/v1/admin/registrations/${esc(r.id)}/passes/${esc(s.pass.id)}.pdf">Download</a>`:''}${r?`<button type="button" class="quiet speaker-open" data-rid="${esc(r.id)}" title="Open registration">${esc(r.reference)}</button>`:''}</div></li>`;}
// Portraits are 480 x 600, shown at 40 px. Drawing them as <img> made Chrome
// decode full-size images while scrolling, so the list stuttered and painted
// blank. Each portrait is decoded once, off the main thread, into a small
// bitmap that every later render reuses; rows show initials until it is ready.
const avatarCache=new Map();
function avatarBitmap(url){if(!avatarCache.has(url))avatarCache.set(url,(async()=>{const img=new Image();img.decoding='async';img.src=url;await img.decode();const side=Math.min(img.naturalWidth,img.naturalHeight);return createImageBitmap(img,(img.naturalWidth-side)/2,(img.naturalHeight-side)*0.3,side,side,{resizeWidth:80,resizeHeight:80,resizeQuality:'high'});})().catch(()=>null));return avatarCache.get(url);}
function speakerAvatars(root){root.querySelectorAll('span.speaker-avatar[data-src]').forEach(async el=>{const bmp=await avatarBitmap(el.dataset.src);if(!bmp||!el.isConnected)return;const c=document.createElement('canvas');c.width=c.height=80;c.className='speaker-avatar';c.setAttribute('aria-hidden','true');c.getContext('2d').drawImage(bmp,0,0);el.replaceWith(c);});}
function speakerMatches(s){const q=speakerQuery.trim().toLowerCase();return (!speakerTab||speakerState(s)===speakerTab)&&(!q||[s.name,s.role,s.organization,speakerContact(s)?.email,s.registration?.reference].some(v=>String(v||'').toLowerCase().includes(q)));}
function speakersRender(onlyId){const counts={};for(const s of speakerRows)counts[speakerState(s)]=(counts[speakerState(s)]||0)+1;document.getElementById('speaker-tabs').innerHTML=speakerTabs.map(([k,l])=>{const n=k?counts[k]||0:speakerRows.length;return `<button type="button" class="status-tab${n===0?' is-empty':''}" data-tab="${k}" aria-pressed="${speakerTab===k}">${esc(l)}<span class="status-tab-count">${n}</span></button>`;}).join('');const ready=counts.ready||0,saved=counts.saved||0,bulk=document.getElementById('speaker-send-all'),issue=document.getElementById('speaker-issue-all');bulk.disabled=!ready;bulk.textContent=ready?`Send ${ready} unsent pass${ready===1?'':'es'}`:'No passes to send';issue.hidden=!saved;issue.textContent=`Issue ${saved} pass${saved===1?'':'es'}`;const shown=speakerRows.filter(speakerMatches),li=onlyId&&document.querySelector(`.speaker-row[data-id="${CSS.escape(onlyId)}"]`),one=speakerRows.find(s=>s.id===onlyId);if(li&&one){li.outerHTML=speakerRow(one);speakerAvatars(document.querySelector(`.speaker-row[data-id="${CSS.escape(onlyId)}"]`));return;}document.getElementById('speaker-count').textContent=`${shown.length} of ${speakerRows.length} speakers`;document.getElementById('speaker-list').innerHTML=shown.map(speakerRow).join('')||`<li class="admin-empty"><strong>${speakerRows.length?'No speakers match.':'No speakers yet.'}</strong><span>${speakerRows.length?'Try another search or tab.':'Add speakers in the Mobile app editor; they appear here to receive passes.'}</span></li>`;speakerAvatars(document.getElementById('speaker-list'));}
async function speakersReload(onlyId){speakerRows=(await api('/admin/speakers')).speakers;speakersRender(onlyId);}
async function speakersPage(){app.innerHTML=`<div class="admin-page speakers-page"><button id="return" class="secondary back-button"><span aria-hidden="true">&larr;</span> Back to registrations</button><header class="admin-heading"><div><p class="admin-kicker">Staff console</p><h1>Speakers</h1><p class="admin-intro">Save each speaker's email and phone, issue their pass, then send it by email and WhatsApp. Nothing is issued or sent until you choose to. Names and roles come from the Mobile app editor.</p></div><div class="admin-header-actions"><button id="speaker-issue-all" class="secondary" hidden>Issue passes</button><button id="speaker-send-all" disabled>Send unsent passes</button></div></header><div class="speaker-toolbar"><label class="admin-search">Search<span class="search-field"><input id="speaker-search" type="search" value="${esc(speakerQuery)}" placeholder="Name, organisation, email or reference" autocomplete="off"></span></label><p id="speaker-count" class="admin-result-count" aria-live="polite"></p></div><div id="speaker-tabs" class="status-tabs" role="group" aria-label="Filter speakers"></div><ul id="speaker-list" class="speaker-list" aria-busy="true">${[0,1,2,3,4].map(()=>`<li class="speaker-row">${skeleton(70)}</li>`).join('')}</ul></div>`;window.scrollTo({top:0});
bind('return','click',()=>{history.pushState(null,'','/admin');return adminList();});
document.getElementById('speaker-search').addEventListener('input',e=>{speakerQuery=e.target.value;speakersRender();});
document.getElementById('speaker-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;speakerTab=b.dataset.tab;speakersRender();});
bind('speaker-send-all','click',async e=>{const ready=speakerRows.filter(s=>speakerState(s)==='ready');if(!ready.length||!confirm(`Send ${ready.length} speaker${ready.length===1?'':'s'} their pass now, by email and by WhatsApp where ticked?`))return;await busy(e.target,async()=>{const out=await post('/admin/bulk-send',{ids:ready.map(s=>s.registration.id),channel:''}),bad=ready.filter(s=>out[s.registration.id]!=='queued');await speakersReload();message(bad.length?`Queued ${ready.length-bad.length}. Not sent: ${bad.map(s=>`${s.name} (${out[s.registration.id]})`).join('; ')}`:`Queued ${ready.length} pass${ready.length===1?'':'es'}.`,bad.length>0);},'Sending…');speakersRender();});
bind('speaker-issue-all','click',async e=>{const saved=speakerRows.filter(s=>speakerState(s)==='saved');if(!saved.length||!confirm(`Issue passes for ${saved.length} speaker${saved.length===1?'':'s'}? Nothing is emailed until you send them.`))return;const bad=[];await busy(e.target,async()=>{for(const s of saved){try{await post(`/admin/speakers/${encodeURIComponent(s.id)}/pass`,{},{'Idempotency-Key':uuid()+uuid()});}catch(err){bad.push(`${s.name} (${err.message})`);}}await speakersReload();},'Issuing…');speakersRender();message(bad.length?`Issued ${saved.length-bad.length}. Not issued: ${bad.join('; ')}`:`Issued ${saved.length} pass${saved.length===1?'':'es'}. Send them when ready.`,bad.length>0);});
const list=document.getElementById('speaker-list');
const find=id=>speakerRows.find(s=>s.id===id),refreshRow=async id=>{await speakersReload(id);list.querySelector(`.speaker-row[data-id="${CSS.escape(id)}"]`)?.classList.add('is-updated');};
list.addEventListener('input',e=>{const f=e.target.closest('.speaker-contact');if(!f)return;const s=find(f.dataset.id),a=speakerContact(s),phone=f.phone.value.trim();f.whatsapp.disabled=!phone;const dirty=f.email.value.trim().toLowerCase()!==(a?.email||'')||phone!==(a?.phone||'')||(!!phone&&f.whatsapp.checked)!==!!a?.whatsapp_consent;f.querySelector('.speaker-save').hidden=!dirty||!f.email.value.trim();});
list.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,s=find(f.dataset.id),btn=f.querySelector('.speaker-save'),a=speakerContact(s);if(btn.hidden)return;if(!f.email.checkValidity()||!f.email.value.includes('@')){message(`Enter a valid email for ${s.name}.`,true);f.email.focus();return;}if(!f.phone.checkValidity()){message('Phone must be international, like +919876543210.',true);f.phone.focus();return;}message('');try{await busy(btn,async()=>{await post('/admin/speakers/'+encodeURIComponent(s.id),{email:f.email.value.trim(),phone:f.phone.value.trim(),whatsapp_consent:f.whatsapp.checked&&!!f.phone.value.trim()});await refreshRow(s.id);message(`Email saved for ${s.name}.${s.pass?' Their pass now goes to this address.':' No pass has been issued.'}`);},'Saving…');}catch(err){message(err.message,true);}});
list.addEventListener('click',async e=>{const send=e.target.closest('.speaker-send'),open=e.target.closest('.speaker-open'),issue=e.target.closest('.speaker-issue'),print=e.target.closest('.speaker-print');if(print){const s=find(print.closest('.speaker-row').dataset.id);if(!confirm(`Issue a pass for ${s.name} without an email or phone?\n\nIt cannot be emailed or sent. Download it and hand it over. If you add an email later, you can send the same pass.`))return;message('');try{await busy(print,async()=>{const out=await post(`/admin/speakers/${encodeURIComponent(s.id)}/pass`,{without_contact:true},{'Idempotency-Key':uuid()+uuid()});await refreshRow(s.id);const fresh=find(s.id);message(`Pass issued for ${s.name}. Downloading it now; it is also under Download on the row.`);if(fresh?.pass)location.assign(`/api/v1/admin/registrations/${out.registration_id}/passes/${fresh.pass.id}.pdf`);},'Issuing…');}catch(err){message(err.message,true);}return;}if(issue){const s=find(issue.closest('.speaker-row').dataset.id);message('');try{await busy(issue,async()=>{await post(`/admin/speakers/${encodeURIComponent(s.id)}/pass`,{},{'Idempotency-Key':uuid()+uuid()});await refreshRow(s.id);message(`Pass issued for ${s.name}. Send it when ready.`);},'Issuing…');}catch(err){message(err.message,true);}return;}if(open){history.replaceState({...history.state,scroll:scrollY},'');history.pushState({fromList:true},'','/admin?registration='+encodeURIComponent(open.dataset.rid));return adminDetail(open.dataset.rid,{top:true}).catch(err=>message(err.message,true));}if(!send)return;const s=find(send.closest('.speaker-row').dataset.id);message('');try{await busy(send,async()=>{await post(`/admin/registrations/${s.registration.id}/review`,{action:send.dataset.action,pass_id:s.pass.id,request_id:uuid()});await refreshRow(s.id);message(`Pass queued for ${s.name} by email${s.attendee.whatsapp_consent&&s.attendee.phone?' and WhatsApp':''}.`);},'Sending…');}catch(err){message(err.message,true);}});
try{await speakersReload();}finally{list.removeAttribute('aria-busy');}}
async function freeLinksPage(revealed=''){const d=await api('/admin/free-links'),now=new Date(d.server_time),parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now),today=`${parts.find(p=>p.type==='year').value}-${parts.find(p=>p.type==='month').value}-${parts.find(p=>p.type==='day').value}`,links=d.items.map(l=>({...l,active:!l.revoked_at&&new Date(l.expires_at)>now,type:l.registration_kind==='exhibitor'?'Exhibitors':'Delegates'}));app.innerHTML=`<button id="return" class="secondary">Back to registrations</button><h1>Free registration links.</h1><p>Create complimentary links for delegates or exhibitors. Generating a replacement expires only the active link for the same registration type.</p><form id="generate-free-link" class="card"><h2>Generate link</h2><label>Registration type<select name="registration_kind"><option value="delegate">Delegates</option><option value="exhibitor">Exhibitors</option></select></label>${field('Usable through','expires_on',today,'date',`min="${today}"`)}<label class="check"><input type="checkbox" name="auto_approve" checked>Approve registrations automatically and issue passes immediately.</label><p class="help">Clear this option when registrations from the link should wait for organiser review. Exhibitors still provide their institution logo and attendee details. The link works through the end of the selected date in India time.</p><button>Generate new link</button></form>${revealed?`<div class="card"><h2>New link</h2><label>Copy and share this link<input id="generated-free-url" class="mono" value="${esc(revealed)}" readonly></label><div class="actions"><button id="copy-free-link">Copy link</button></div><p class="help">For security, this is the only time the complete link is shown.</p></div>`:''}<div class="card"><h2>Link history</h2>${links.length?`<div class="table-scroll"><table><thead><tr><th>Status</th><th>Registration type</th><th>Approval</th><th>Usable through</th><th>Registrations</th><th>Created by</th><th>Action</th></tr></thead><tbody>${links.map(l=>`<tr><td>${l.active?'Active':l.revoked_at?'Expired manually':'Expired'}</td><td>${esc(l.type)}</td><td>${l.auto_approve?'Automatic':'Needs review'}</td><td>${esc(String(l.expires_on).slice(0,10))}</td><td>${esc(l.use_count)}</td><td>${esc(l.created_by)}</td><td>${l.active?`<button class="expire-free-link danger" data-id="${l.id}" data-type="${esc(l.registration_kind)}">Expire this link</button>`:'-'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No records yet.</p>'}</div>`;window.scrollTo({top:0});bind('return','click',adminList);bind('generate-free-link','submit',async e=>{e.preventDefault();const f=new FormData(e.target),kind=f.get('registration_kind');if(links.some(l=>l.registration_kind===kind&&l.active)&&!confirm(`Generate a new ${kind} link and immediately expire the active one?`))return;await busy(e.submitter,async()=>{const out=await post('/admin/free-links',{registration_kind:kind,expires_on:f.get('expires_on'),auto_approve:f.has('auto_approve')});message('New free registration link generated.');await freeLinksPage(out.url);},'Generating…');});bind('copy-free-link','click',async()=>{await navigator.clipboard.writeText(document.getElementById('generated-free-url').value);message('Free registration link copied.');});document.querySelectorAll('.expire-free-link').forEach(el=>el.addEventListener('click',async()=>{if(!confirm(`Expire this ${el.dataset.type} link now? Anyone using it will no longer be able to register.`))return;try{await post(`/admin/free-links/${el.dataset.id}/expire`,{});message(`${el.dataset.type==='exhibitor'?'Exhibitor':'Delegate'} free registration link expired.`);await freeLinksPage();}catch(err){message(err.message,true);}}));}
async function categoryAdmin(){await loadConfig();app.innerHTML=`<h1>Category availability.</h1><p>Closing stops new registrations. Paid and free-link registration are controlled separately. Existing registrations can still submit payment evidence.</p><div class="card"><div class="table-scroll"><table><thead><tr><th>Category</th><th>Fee</th><th>Paid registration</th><th>Free links</th></tr></thead><tbody>${config.categories.map(c=>`<tr><td>${esc(c.label)}</td><td>${c.free_only?'Free-link only':money(c.payable_paise)}</td><td>${c.free_only?'-':`<label class="check"><input class="category-toggle" type="checkbox" data-id="${c.id}" data-field="open" ${c.open?'checked':''}>Open</label>`}</td><td><label class="check"><input class="category-toggle" type="checkbox" data-id="${c.id}" data-field="free_open" ${c.free_open?'checked':''}>Open</label></td></tr>`).join('')}</tbody></table></div></div><button id="return">Back to registrations</button>`;document.querySelectorAll('.category-toggle').forEach(el=>el.addEventListener('change',async()=>{try{await post('/admin/categories',{id:el.dataset.id,[el.dataset.field]:el.checked});message('Availability saved.');}catch(e){el.checked=!el.checked;message(e.message,true);}}));bind('return','click',adminList);}
async function adminDetail(rid,{push=false,top=false}={}){const d=await api('/admin/registrations/'+rid),r=d.registration;if(d.category.kind==='exhibitor'&&!config)await loadConfig();if(push){history.replaceState({...history.state,scroll:scrollY},'');const p=listParams();p.set('registration',rid);history.pushState({fromList:true},'','?'+p);}app.innerHTML=`<button id="return" class="secondary back-button"><span aria-hidden="true">&larr;</span> Back to registrations</button><h1>${esc(r.reference)}</h1><p><span class="pill">${esc(r.status)}</span> ${esc(d.category.label)}</p><div class="card"><h2>Registration details</h2>${pairs([['Institution',r.institution],['Contact',r.contact_name],['Email',r.email],['Phone',r.phone],['Description',r.description],['Coupon',r.coupon_code?`${r.coupon_code} - ${r.discount_percent}% off, paid by bank transfer`:'None'],['Current fee',money(d.payable_paise)],['Original quote',money(r.quoted_paise)],...assigned(d),['Organiser note',r.review_note]])}${stallNumberForm(d)}${stallForm(d)}${allowanceForm(d)}<h3>Attendees</h3>${attendeeTable(d)}${r.status==='approved'&&d.passes.some(p=>!p.revoked_at)?`<div class="actions pass-pack"><a class="button secondary" href="/api/v1/admin/registrations/${esc(r.id)}/passes/all.zip">Download all passes (ZIP)</a></div>`:''}<div id="attendee-edit"></div><h3>Private files</h3><div class="actions">${d.files.map(f=>`<a class="button secondary" href="/api/v1/admin/registrations/${rid}/files/${f.id}">Download ${esc(f.kind)} (${date(f.created_at)})</a>`).join('')||'No files uploaded.'}</div>${d.category.kind==='exhibitor'&&r.status!=='cancelled'?`<form id="admin-logo-form" class="admin-logo-form"><label>${d.files.some(f=>f.kind==='logo')?'Replace institution logo':'Upload institution logo on the exhibitor’s behalf'} (PNG or JPEG, up to 5 MB)<input type="file" name="logo" accept="image/png,image/jpeg" required></label>${r.status==='approved'?'<p class="help">The public exhibitor directory shows the newest logo.</p>':''}<button>Upload logo</button></form>`:''}</div><div class="card"><h2>Payment submissions</h2>${table(d.payments.map(p=>({...p,amount:money(p.amount_paise),payment_date:day(p.payment_date),verified_date:day(p.verified_date),verified_amount:p.verified_at?money(p.verified_amount_paise):'',verified_at:p.verified_at?date(p.verified_at):'Not yet verified'})),[['id','Submission ID'],['bank_reference','Reported reference'],['payment_date','Reported date'],['amount','Reported amount'],['verified_reference','Verified reference'],['verified_date','Verified date'],['verified_amount','Verified amount'],['verified_at','Verified at']])}</div>${r.status==='awaiting_review'?reviewForm(d):r.status==='awaiting_payment'?reviewForm(d,true):r.status==='rejected'?reinstateForm(d):''}${attendeeForm(d,true)}<div class="card"><h2>Registration actions</h2>${openPlaces(d)>0?'<form id="roster-notice-form"><p class="help">Emails the contact how many passes are unassigned and a single-use link to add attendees, valid for 7 days. One notice per registration every 24 hours.</p><button class="secondary">Send add-attendee notice</button></form>':''}${r.status==='awaiting_payment'?'<form id="remind-form"><p class="help">Emails the contact the fee due and a single-use link to this registration, valid for 7 days. One reminder per registration every 24 hours.</p><button class="secondary">Send payment reminder</button></form>':''}${r.status==='approved'&&d.category.download_only?'<p class="help">Guest passes are download only: nothing is emailed or sent by WhatsApp. Download the pass from the attendee row and hand it over.</p>':''}${r.status==='approved'&&!d.category.download_only?`<form id="send-form"><label>Channel<select name="channel"><option value="">Email and permitted WhatsApp</option><option value="email">Email only</option><option value="whatsapp">Permitted WhatsApp only</option></select></label><div class="actions"><button value="send">Send passes</button><button value="resend" class="secondary">Resend existing passes</button></div><p class="help">Send queues initial delivery once. Resend uses the existing passes.</p></form>`:''}${r.status!=='cancelled'?'<form id="cancel-form"><label>Cancellation reason<textarea name="note" required></textarea></label><p class="help">Cancellation revokes all passes. Handle refunds manually.</p><button class="danger">Cancel registration</button></form>':''}</div><div class="card"><h2>Pass history</h2>${table(d.passes.map(p=>({...p,revoked_at:p.revoked_at?date(p.revoked_at):'Active'})),[['number','Pass number'],['version','Version'],['attendee_id','Attendee ID'],['revoked_at','Revoked at']])}${r.status==='approved'?`<form id="reissue-form"><label>Pass to reissue<select name="pass_id">${d.passes.filter(p=>!p.revoked_at).map(p=>`<option value="${p.id}">${esc(r.attendees.find(a=>a.id===p.attendee_id)?.name)} · ${esc(p.number)}</option>`).join('')}</select></label><label>Reason<textarea name="note" required></textarea></label><p class="help">Reissue revokes the previous pass, its QR identifier and its pass number, and issues a replacement. Nothing is sent: send the new pass from the attendee list when ready.</p><button class="secondary">Reissue pass</button></form>`:''}</div><div class="card"><h2>Delivery history</h2>${table(d.deliveries.map(j=>({...j,created_at:date(j.created_at)})),[['id','Job ID'],['purpose','Purpose'],['channel','Channel'],['recipient','Recipient'],['status','Status'],['attempts','Attempts'],['error_code','Outcome'],['provider_id','Provider ID'],['created_at','Created']])}${d.deliveries.filter(j=>['failed','uncertain'].includes(j.status)).map(j=>`<form class="retry-form" data-id="${j.id}"><p>${esc(j.channel)} · ${esc(j.recipient)} · ${esc(j.status)}</p>${j.status==='uncertain'?'<label class="check"><input type="checkbox" name="confirm_uncertain" required>I checked the provider and accept that retrying may send a duplicate.</label><label>Provider check note<input name="note" required></label>':''}<button class="secondary">Retry ${esc(j.id)}</button></form>`).join('')}</div><div class="card"><h2>Audit trail</h2>${table(d.audit.map(a=>({...a,created_at:date(a.created_at)})),[['created_at','Time'],['staff_email','Staff'],['action','Action'],['detail','Details']])}</div>`;
if(push||top)window.scrollTo({top:0});bind('return','click',e=>busy(e.currentTarget,backToList,'Loading…'));bind('admin-logo-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{const file=new FormData(e.target).get('logo');await upload(rid,'logo',file,{'X-CSRF-Token':csrf()},'/api/v1/admin/registrations');message('Logo uploaded.');await adminDetail(rid);});});bind('review-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{const f=new FormData(e.target),action=e.submitter.value;await post(`/admin/registrations/${rid}/review`,{action,note:f.get('note'),payment_id:f.get('payment_id'),verified_reference:f.get('verified_reference'),verified_date:f.get('verified_date'),verified_amount_paise:action.includes('approve')||action==='reinstate'?paise(f.get('amount')):0,successful:f.has('successful'),beneficiary_confirmed:f.has('beneficiary_confirmed'),accept_amount:f.has('accept_amount')});message('Review saved.');await adminDetail(rid);});});bind('remind-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/review`,{action:'payment_reminder'});message('Payment reminder queued.');await adminDetail(rid);},'Sending…');});bind('roster-notice-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/review`,{action:'roster_notice'});message('Add-attendee notice queued.');await adminDetail(rid);},'Sending…');});bind('attendee-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/attendees`,attendeeBody(e.target));message('Attendee added.');await adminDetail(rid);});});bind('send-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/review`,{action:e.submitter.value,channel:new FormData(e.target).get('channel'),request_id:uuid()});message('Delivery queued.');await adminDetail(rid);});});
bindAttendeeActions(d);bind('allowance-form','submit',async e=>{e.preventDefault();const f=new FormData(e.target);await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/allowance`,{roster_count:Number(f.get('roster_count')),note:f.get('note')});message(`Pass allowance set to ${f.get('roster_count')}.`);await adminDetail(rid);});});bind('stall-number-form','submit',async e=>{e.preventDefault();const f=new FormData(e.target),n=String(f.get('stall_number')).trim();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/stall-number`,{stall_number:n,note:f.get('note')});message(n?`Stall number set to ${n.toUpperCase()}.`:'Stall allocation cleared.');await adminDetail(rid);});});bind('category-form','submit',async e=>{e.preventDefault();const f=new FormData(e.target),to=config.categories.find(c=>c.id===f.get('category_id')),extra=Math.max(r.attendees.length-to.roster_count,0);if(!confirm(`Move ${r.reference} to ${to.label} (${to.roster_count} passes)?${extra?` All ${r.attendees.length} attendees keep their passes; ${extra} ${extra===1?'becomes an extra pass':'become extra passes'}.`:''} Nothing is sent to the exhibitor.`))return;await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/category`,{category_id:f.get('category_id'),note:f.get('note')});message(`Stall type changed to ${to.label}.`);await adminDetail(rid);});});
for(const [form,action]of [['cancel-form','cancelled'],['reissue-form','reissue']])bind(form,'submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/review`,{action,...Object.fromEntries(new FormData(e.target))});message('Action saved.');await adminDetail(rid);});});
document.querySelectorAll('.retry-form').forEach(el=>el.addEventListener('submit',async e=>{e.preventDefault();try{await busy(e.submitter,async()=>{const f=new FormData(el);await post('/admin/retry',{id:el.dataset.id,confirm_uncertain:f.has('confirm_uncertain'),note:f.get('note')||''});message('Retry queued.');await adminDetail(rid);});}catch(e){message(e.message,true);}}));}
// Staff corrections never deliver anything on their own: each pass is sent
// from its row here, or with "Send passes", once the team is ready.
function activePass(d,aid){return d.passes.find(p=>p.attendee_id===aid&&!p.revoked_at);}
function passSent(d,pass){return d.deliveries.some(j=>j.pass_id===pass.id&&j.purpose==='pass'&&j.status!=='cancelled');}
function attendeeTable(d){const r=d.registration;if(!r.attendees.length)return '<p class="muted">No records yet.</p>';const editable=r.status!=='cancelled',approved=r.status==='approved',guest=d.category.download_only;return `<div class="table-scroll"><table><thead><tr><th scope="col">Name</th><th scope="col">Designation</th><th scope="col">Email</th><th scope="col">Phone</th><th scope="col">WhatsApp</th>${approved?'<th scope="col">Pass</th>':''}${editable?'<th scope="col">Actions</th>':''}</tr></thead><tbody>${r.attendees.map(a=>{const pass=activePass(d,a.id),sent=pass&&passSent(d,pass);return `<tr><td>${esc(a.name)}</td><td>${esc(a.designation)}</td><td>${esc(a.email)}</td><td>${esc(a.phone)}</td><td>${a.whatsapp_consent?'Permitted':'Not permitted'}</td>${approved?`<td>${pass?`<span class="mono">${esc(pass.number)}</span><br><small>${guest?'Download only':sent?'Sent':'Not sent'}</small>`:'-'}</td>`:''}${editable?`<td><div class="row-actions">${approved&&pass?`${guest?'':`<button type="button" class="send-pass" data-pass="${esc(pass.id)}" data-action="${sent?'resend':'send'}" data-name="${esc(a.name)}">${sent?'Resend pass':'Send pass'}</button>`}<a class="button secondary" href="/api/v1/admin/registrations/${esc(r.id)}/passes/${esc(pass.id)}.pdf">Download pass</a>`:''}<button type="button" class="secondary edit-attendee" data-id="${esc(a.id)}">Edit</button>${r.attendees.length>1?`<button type="button" class="danger remove-attendee" data-id="${esc(a.id)}" data-name="${esc(a.name)}">Remove</button>`:''}</div></td>`:''}</tr>`;}).join('')}</tbody></table></div>`;}
function attendeeEditForm(d,a){const pass=d.registration.status==='approved'&&activePass(d,a.id);if(d.category.download_only)return `<form id="attendee-edit-form" class="inline-form" data-id="${esc(a.id)}"><h3>Edit ${esc(a.name)}</h3><div class="fields">${field('Full name','name',a.name,'text','maxlength="120"')}${optField('Designation (optional)','designation',a.designation,'text','maxlength="180"')}${optField('Email (optional)','email',a.email,'email')}${optField('Phone (optional, e.g. +919876543210)','phone',a.phone,'tel',phonePattern)}</div><p class="help">Saving sends nothing; guest passes are download only.${pass?' The pass keeps its number and QR code and shows the new details when next downloaded.':''}</p><div class="actions"><button>Save attendee</button><button type="button" id="attendee-edit-cancel" class="secondary">Cancel</button></div></form>`;return `<form id="attendee-edit-form" class="inline-form" data-id="${esc(a.id)}"><h3>Edit ${esc(a.name)}</h3><div class="fields">${field('Full name','name',a.name,'text','maxlength="120"')}${field('Designation','designation',a.designation,'text','maxlength="180"')}${emailOptional(d.category.id)?eitherContactFields(a.email,a.phone,'email','phone'):`${field('Email','email',a.email,'email')}${field('Phone (e.g. +919876543210)','phone',a.phone,'tel',phonePattern)}`}</div><label class="check"><input type="checkbox" name="whatsapp_consent" ${a.whatsapp_consent?'checked':''}>I have permission to send this attendee their Bio Connect 4.0 pass and delivery updates by WhatsApp.</label><p class="help">Saving sends nothing.${pass?' The pass keeps its number and QR code and shows the new details when next downloaded. If it was already sent, resend it so the attendee has the updated copy.':''}${d.category.kind==='delegate'?' The registration contact is updated to match.':''}</p><div class="actions"><button>Save attendee</button><button type="button" id="attendee-edit-cancel" class="secondary">Cancel</button></div></form>`;}
function bindAttendeeActions(d){const r=d.registration,rid=r.id,holder=document.getElementById('attendee-edit');
document.querySelectorAll('.edit-attendee').forEach(el=>el.addEventListener('click',()=>{message('');holder.innerHTML=attendeeEditForm(d,r.attendees.find(a=>a.id===el.dataset.id));holder.querySelector('input')?.focus();bind('attendee-edit-cancel','click',()=>{holder.innerHTML='';});bind('attendee-edit-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/attendees/${e.target.dataset.id}`,attendeeBody(e.target));message('Attendee updated. Nothing was sent.');await adminDetail(rid);});});}));
document.querySelectorAll('.remove-attendee').forEach(el=>el.addEventListener('click',async()=>{message('');if(!confirm(`Remove ${el.dataset.name} from ${r.reference}?${r.status==='approved'?' Their pass and QR code are revoked.':''}`))return;try{await busy(el,async()=>{await post(`/admin/registrations/${rid}/attendees/${el.dataset.id}/remove`,{note:''});message(`${el.dataset.name} removed.`);await adminDetail(rid);},'Removing…');}catch(err){message(err.message,true);}}));
document.querySelectorAll('.send-pass').forEach(el=>el.addEventListener('click',async()=>{message('');try{await busy(el,async()=>{await post(`/admin/registrations/${rid}/review`,{action:el.dataset.action,pass_id:el.dataset.pass,request_id:uuid()});message(`Pass queued for ${el.dataset.name}.`);await adminDetail(rid);},'Sending…');}catch(err){message(err.message,true);}}));}
function stallNumberForm(d){const r=d.registration;if(d.category.kind!=='exhibitor'||r.status==='cancelled')return '';return `<form id="stall-number-form" class="inline-form"><div class="fields"><label>Stall number<input name="stall_number" maxlength="16" value="${esc(r.stall_number||'')}" placeholder="e.g. A-12" autocomplete="off"></label><label>Reason (optional)<input name="note" maxlength="2000"></label></div><p class="help">${r.stall_number?`Currently stall ${esc(r.stall_number)}.`:'No stall allocated yet.'} Approved exhibitors appear in the public directory and the mobile app with this number. Leave it empty to clear the allocation. Nothing is sent.</p><div class="actions"><button class="secondary">Save stall number</button></div></form>`;}
function stallForm(d){const r=d.registration;if(d.category.kind!=='exhibitor'||r.status==='cancelled'||!config)return '';const others=config.categories.filter(c=>c.kind==='exhibitor'&&c.id!==r.category_id);if(!others.length)return '';return `<form id="category-form" class="inline-form"><div class="fields"><label>Change stall type<select name="category_id">${others.map(c=>`<option value="${esc(c.id)}">${esc(c.label)} · ${c.roster_count} passes</option>`).join('')}</select></label><label>Reason (optional)<input name="note" maxlength="2000"></label></div><p class="help">Passes follow the new stall's allowance and keep any extra passes granted. Moving to a smaller stall removes nobody: attendees beyond the new allowance stay as extra passes. Issued passes, the reference and payments stay as they are, and nothing is sent.${r.status==='approved'?' Settle any fee difference outside the system.':''}</p><div class="actions"><button class="secondary">Change stall type</button></div></form>`;}
function allowanceForm(d){const r=d.registration,included=d.category.roster_count;if(d.category.kind!=='exhibitor'||r.status==='cancelled')return '';return `<form id="allowance-form" class="inline-form"><div class="fields"><label>Pass allowance<input name="roster_count" type="number" min="${Math.max(1,r.attendees.length)}" max="50" step="1" value="${r.roster_count}" required></label><label>Reason (optional)<input name="note" maxlength="2000"></label></div><p class="help">${esc(d.category.label)} includes ${included} passes${r.roster_count>included?`; this registration has ${r.roster_count-included} extra`:''}. Raise it to add extra passes, then fill them with Add an attendee below. Nothing is sent, and any fee is settled outside the system.</p><div class="actions"><button class="secondary">Save pass allowance</button></div></form>`;}
// Approving an amount other than the fee due needs an explicit tick and a
// reason in the note; the server records both amounts in the audit trail.
function amountAccept(due,on=false){return `<label class="check"><input type="checkbox" name="accept_amount" ${on?'checked':''}>The bank shows a different amount</label><div class="banner warning amount-warning" ${on?'':'hidden'}><strong>You are approving an amount different from the fee.</strong> ${due?`The fee for a payment made today is ${money(due)}; it can differ by payment date. `:''}Approve only if the bank's reconciliation report shows the amount you entered, and give the reason in the note below. Both amounts, the reason and your name are kept in the audit trail.</div>`;}
document.addEventListener('change',e=>{if(e.target.name!=='accept_amount')return;const form=e.target.form,note=form?.querySelector('[name=note]');form?.querySelector('.amount-warning')?.toggleAttribute('hidden',!e.target.checked);if(note){note.required=e.target.checked;note.minLength=e.target.checked?10:0;note.placeholder=e.target.checked?'Why the bank amount differs from the fee (required)':'';}});
function reinstateForm(d){const free=d.registration.free_registration,p=d.payments[0];return `<form id="review-form" class="card"><h2>Approve rejected registration</h2><p>${free?'This registration is complimentary. No payment verification is required.':'Verify the payment against the bank’s reconciliation report, entering the transaction as it appears there.'} Approval issues the passes without sending them. Send them from the attendee list or with Send passes when ready.</p>${free?'<input type="hidden" name="amount" value="0.01">':`<input type="hidden" name="payment_id" value="${esc(p?.id)}">${p?`<p class="help">Latest submission: ${esc(p.bank_reference)} · ${money(p.amount_paise)} · ${day(p.payment_date)}</p>`:''}<div class="fields">${field('Verified bank reference','verified_reference')}${field('Verified payment date','verified_date','','date')}${field('Verified amount in INR','amount','','number','min="0.01" step="0.01"')}</div>${amountAccept(d.payable_paise)}<label class="check"><input type="checkbox" name="successful" required>I verified the transaction succeeded.</label><label class="check"><input type="checkbox" name="beneficiary_confirmed" required>I verified the correct beneficiary.</label>`}<label>Review note<textarea name="note"></textarea></label><div class="actions"><button value="reinstate">Approve without sending</button></div></form>`;}
function reviewForm(d,record=false){if(d.registration.free_registration)return `<form id="review-form" class="card"><h2>Review complimentary registration</h2><p>This registration is complimentary. No payment verification is required.</p><input type="hidden" name="amount" value="0.01"><label>Review note / rejection reason<textarea name="note"></textarea></label><div class="actions"><button value="approve_send">Approve and send pass</button><button value="approve_only" class="secondary">Approve only</button><button value="rejected" class="danger" formnovalidate>Reject</button></div></form>`;const missingLogo=record&&d.category.kind==='exhibitor'&&!d.files.some(f=>f.kind==='logo');return `<form id="review-form" class="card"><h2>${record?'Record payment found in SBI':'Verify against bank records'}</h2><p>${record?'Use this only when SBI confirms a payment that the registrant did not submit. This creates the payment record and approves the registration.':'Approve only against the bank’s reconciliation report, entering the transaction as it appears there.'}</p>${missingLogo?'<div class="banner warning"><strong>Institution logo missing.</strong> Upload it above on the exhibitor’s behalf, or ask them to add it themselves, before recording and approving this payment.</div>':''}<input type="hidden" name="payment_id" value="${esc(d.payments[0]?.id)}"><div class="fields">${field('Verified bank reference','verified_reference')}${field('Verified payment date','verified_date','','date')}${field('Verified amount in INR','amount','','number','min="0.01" step="0.01"')}</div>${amountAccept(d.payable_paise)}<label class="check"><input type="checkbox" name="successful" required>I verified the transaction succeeded.</label><label class="check"><input type="checkbox" name="beneficiary_confirmed" required>I verified the correct beneficiary.</label><label>${record?'Review note':'Review note / correction or rejection reason'}<textarea name="note"></textarea></label><div class="actions">${record?`<button value="record_approve_send" ${missingLogo?'disabled':''}>Record, approve and send</button><button value="record_approve_only" class="secondary" ${missingLogo?'disabled':''}>Record and approve only</button>`:'<button value="approve_send">Approve and send</button><button value="approve_only" class="secondary">Approve only</button><button value="correction_requested" class="secondary" formnovalidate>Request correction</button><button value="rejected" class="danger" formnovalidate>Reject</button>'}</div></form>`;}
async function accountsPage(){const accounts=await api('/admin/staff');app.innerHTML=`<h1>Staff accounts.</h1><p>Account managers administer access. Reviewers administer registrations and payments.</p><nav class="admin-tools" aria-label="Staff tools"><button id="mobile-app" class="tool-link">Mobile app</button><button id="posters" class="tool-link">Social posters</button><button id="logout" class="tool-link tool-signout">Sign out</button></nav><div class="card">${table(accounts.map(a=>({...a,active:a.active?'Yes':'No'})),[['email','Email'],['role','Role'],['active','Active']])}</div><form id="create-account" class="card"><h2>Create individual account</h2><div class="fields">${field('Email','email','','email')}${field('Password (14-72 bytes)','password','','password','minlength="14" maxlength="72"')}<label>Role<select name="role"><option value="reviewer">Registration reviewer</option><option value="manager">Account manager</option></select></label></div><button>Create account</button><p id="enrollment" class="secret" hidden></p></form><form id="edit-account" class="card"><h2>Change access</h2><label>Account<select name="id">${accounts.filter(a=>a.id!==me.id).map(a=>`<option value="${a.id}">${esc(a.email)}</option>`).join('')}</select></label><label>Role<select name="role"><option value="reviewer">Registration reviewer</option><option value="manager">Account manager</option></select></label><label class="check"><input type="checkbox" name="active" checked>Active</label><p class="help">Changing access ends existing sessions for this account.</p><button>Save access</button></form>`;logout();bind('posters','click',()=>posterHome());bind('mobile-app','click',()=>{history.pushState(null,'','/admin?view=mobile');return mobileContentPage();});bind('create-account','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{const out=await post('/admin/staff',Object.fromEntries(new FormData(e.target)));e.target.reset();const el=document.getElementById('enrollment');el.hidden=false;el.textContent='Share securely with this staff member and add to their authenticator: '+out.totp_uri;message('Account created. TOTP is mandatory at sign in.');});});bind('edit-account','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{const f=new FormData(e.target);await post('/admin/staff',{id:f.get('id'),role:f.get('role'),active:f.has('active')});message('Access updated and sessions revoked.');await accountsPage();});});}
(async()=>{try{await loadConfig();if(path==='/delegates'||path==='/exhibitors'){await loadFreeRegistration();formPage();setInterval(async()=>{try{const old=category()?.payable_paise;await loadConfig();const c=category(),el=document.getElementById('current-fee');if(el&&!freeRegistration)el.textContent=money(offer(c.payable_paise));const was=document.getElementById('published-fee');if(was)was.textContent=money(c.payable_paise);if(old!==c.payable_paise&&!freeRegistration)message('Fees have refreshed for the current date. Verified timely payments remain eligible for early-bird fees.');}catch{}},60000);}else if(path.startsWith('/manage/'))await managePage();else if(path==='/recover')await recoveryPage();else if(path==='/admin')await adminPage();}catch(e){app.innerHTML='<h1>We could not load this page.</h1><p>Your saved registration is safe. <a href="">Try again</a> or <a href="/recover">recover by email</a>.</p>';message(e.message,true);}})();
// Email campaigns. Templates are written in code; staff choose one, narrow the
// audience and send. The server snapshots the recipients into a queue, so the
// history page shows each person's outcome and progress continues after leaving.
const campaignStatusNames={approved:'Approved',awaiting_review:'Awaiting review',awaiting_payment:'Awaiting payment',correction_requested:'Correction requested'};
const campaignOutcomes=[['','All','total'],['pending','Pending','pending'],['accepted','Sent','accepted'],['delivered','Delivered','delivered'],['failed','Failed','failed'],['uncertain','Uncertain','uncertain'],['cancelled','Cancelled','cancelled']];
let campaignTimer;
function campaignState(c){return c.cancelled_at?'Cancelled':Number(c.pending)>0?'Sending':'Complete';}
function audienceText(a,categories){const parts=[(a.statuses||[]).map(s=>campaignStatusNames[s]||s).join(', ')];if(a.kinds?.length)parts.push(a.kinds.map(k=>k==='exhibitor'?'Exhibitors':'Delegates').join(', '));if(a.categories?.length)parts.push(a.categories.map(id=>categories.find(c=>c.id===id)?.label||id).join(', '));if(a.pass_holders)parts.push('pass holders');if(a.attendance)parts.push(a.attendance==='attended'?'checked in':'not checked in');if(a.exclude_previous)parts.push('skipping people already sent this email');return parts.join(' · ');}
function openCampaigns(){clearTimeout(campaignTimer);history.pushState(null,'','/admin?view=campaigns');return campaignsPage();}
function openCampaign(id){clearTimeout(campaignTimer);history.pushState(null,'','/admin?view=campaigns&campaign='+encodeURIComponent(id));return campaignDetailPage(id);}
async function campaignsPage(){clearTimeout(campaignTimer);const d=await api('/admin/campaigns'),open=d.templates.filter(t=>t.open),cats=d.categories;
app.innerHTML=`<button id="return" class="secondary">Back to registrations</button><h1>Email campaigns.</h1><p>Send a prepared email to registered participants. Recipients are fixed when you send, each address receives one copy, and progress continues if you leave this page.</p>${open.length?`<form id="campaign-form" class="card"><h2>New campaign</h2><label>Email<select name="template_id">${open.map(t=>`<option value="${esc(t.id)}">${esc(t.label)}</option>`).join('')}</select></label><p id="campaign-template-help" class="help"></p><div class="actions"><button type="button" id="campaign-preview" class="secondary" aria-expanded="false">Show preview</button><button type="button" id="campaign-test" class="secondary">Send test to me</button></div><div id="campaign-preview-frame" class="campaign-preview" hidden></div>
<fieldset><legend>Registration status</legend><div class="check-grid">${Object.entries(campaignStatusNames).map(([v,l])=>`<label class="check"><input type="checkbox" name="statuses" value="${v}" ${v==='approved'?'checked':''}>${esc(l)}</label>`).join('')}</div></fieldset>
<fieldset><legend>Registration type</legend><div class="check-grid"><label class="check"><input type="checkbox" name="kinds" value="delegate">Delegates</label><label class="check"><input type="checkbox" name="kinds" value="exhibitor">Exhibitors</label></div><p class="help">Leave both clear to include every type.</p></fieldset>
<fieldset><legend>Category</legend><div class="check-grid">${cats.map(c=>`<label class="check"><input type="checkbox" name="categories" value="${esc(c.id)}">${esc(c.label)} <span class="muted">(${c.kind==='exhibitor'?'exhibitor':'delegate'})</span></label>`).join('')}</div><p class="help">Leave all clear to include every category.</p></fieldset>
<fieldset><legend>Attendees</legend><label>Venue check-in<select name="attendance"><option value="">Everyone</option><option value="attended">Checked in at least once</option><option value="absent">Not checked in</option></select></label><label class="check"><input type="checkbox" name="pass_holders" checked>Only people holding an active pass</label><label class="check"><input type="checkbox" name="exclude_previous" checked>Skip people who were already sent this email</label></fieldset>
<div class="campaign-audience" aria-live="polite"><p id="campaign-count" class="campaign-count">Counting recipients…</p><p id="campaign-sample" class="help"></p></div><div class="actions"><button id="campaign-send" disabled>Send</button></div></form>`:'<div class="card"><p class="muted">No email is available to send right now.</p></div>'}
<div class="card"><h2>History</h2>${d.campaigns.length?`<div class="table-scroll"><table><thead><tr><th scope="col">Created</th><th scope="col">Email</th><th scope="col">Status</th><th scope="col">Recipients</th><th scope="col">Sent</th><th scope="col">Delivered</th><th scope="col">Failed</th><th scope="col">Created by</th><th scope="col"><span class="sr-only">Action</span></th></tr></thead><tbody>${d.campaigns.map(c=>`<tr><td>${esc(date(c.created_at))}</td><td>${esc(c.template_label||c.template_id)}</td><td>${campaignState(c)}</td><td>${esc(c.total)}</td><td>${Number(c.accepted)+Number(c.delivered)}</td><td>${esc(c.delivered)}</td><td>${Number(c.failed)+Number(c.uncertain)}</td><td>${esc(c.created_by)}</td><td><button class="secondary open-campaign" data-id="${esc(c.id)}">View</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No campaigns yet.</p>'}</div>`;
window.scrollTo({top:0});bind('return','click',()=>{history.pushState(null,'','/admin');return adminList();});document.querySelectorAll('.open-campaign').forEach(b=>b.addEventListener('click',()=>openCampaign(b.dataset.id).catch(e=>message(e.message,true))));
const form=document.getElementById('campaign-form');if(!form)return;let count=0,seq=0,timer;
const selected=()=>{const f=new FormData(form),all=n=>f.getAll(n);return {template_id:f.get('template_id'),audience:{statuses:all('statuses'),kinds:all('kinds'),categories:all('categories'),attendance:f.get('attendance'),pass_holders:f.has('pass_holders'),exclude_previous:f.has('exclude_previous')}};};
const describe=()=>{const t=open.find(t=>t.id===form.template_id.value);document.getElementById('campaign-template-help').textContent=`${t.description} Subject: “${t.subject}”. Can be sent until ${date(new Date(new Date(t.send_by)-1000))}.`;};
const refresh=async()=>{const mine=++seq,send=document.getElementById('campaign-send'),out=document.getElementById('campaign-count'),sample=document.getElementById('campaign-sample');send.disabled=true;out.textContent='Counting recipients…';sample.textContent='';try{const r=await post('/admin/campaigns/audience',selected());if(mine!==seq)return;count=r.count;out.innerHTML=`<strong>${r.count}</strong> ${r.count===1?'recipient':'recipients'}`;sample.textContent=r.sample.length?'Including '+r.sample.map(s=>s.email).join(', ')+(r.count>r.sample.length?' and others.':'.'):'No one matches these filters.';send.textContent=r.count?`Send to ${r.count} ${r.count===1?'recipient':'recipients'}`:'Send';send.disabled=!r.count;}catch(e){if(mine!==seq)return;out.textContent=e.message;}};
const later=()=>{clearTimeout(timer);timer=setTimeout(refresh,250);};
form.addEventListener('change',e=>{if(e.target.name==='template_id'){describe();const f=document.getElementById('campaign-preview-frame');if(!f.hidden)f.innerHTML=`<iframe title="Email preview" src="/api/v1/admin/campaigns/templates/${encodeURIComponent(form.template_id.value)}/preview" sandbox="allow-popups allow-popups-to-escape-sandbox"></iframe>`;}later();});describe();refresh();
bind('campaign-preview','click',e=>{const f=document.getElementById('campaign-preview-frame'),show=f.hidden;f.hidden=!show;e.target.textContent=show?'Hide preview':'Show preview';e.target.setAttribute('aria-expanded',String(show));if(show)f.innerHTML=`<iframe title="Email preview" src="/api/v1/admin/campaigns/templates/${encodeURIComponent(form.template_id.value)}/preview" sandbox="allow-popups allow-popups-to-escape-sandbox"></iframe>`;});
bind('campaign-test','click',e=>busy(e.target,async()=>{const r=await post('/admin/campaigns/test',{template_id:form.template_id.value});message(`Test email sent to ${r.email}.`);},'Sending…'));
form.addEventListener('submit',async e=>{e.preventDefault();message('');const body=selected(),label=open.find(t=>t.id===body.template_id).label;if(!count||!confirm(`Send “${label}” to ${count} ${count===1?'recipient':'recipients'} now? This cannot be undone, though unsent messages can be cancelled.`))return;try{await busy(e.submitter,async()=>{const r=await post('/admin/campaigns',{...body,expected_count:count});message(`Campaign queued for ${r.count} recipients.`);await openCampaign(r.id);},'Queuing…');}catch(err){message(err.message,true);if(/audience changed/.test(err.message))refresh();}});}
async function campaignDetailPage(id){clearTimeout(campaignTimer);let status='',search='',page=1,c;
const load=async()=>{clearTimeout(campaignTimer);const q=new URLSearchParams({status,q:search,page});const d=await api(`/admin/campaigns/${encodeURIComponent(id)}?${q}`);if(document.getElementById('campaign-detail')?.dataset.id!==id)return;c=d.campaign;
document.getElementById('campaign-state').textContent=campaignState(c);const done=Number(c.total)-Number(c.pending);
document.getElementById('campaign-progress').innerHTML=`<progress class="summary-meter" max="${Math.max(1,Number(c.total))}" value="${done}"></progress><p class="help">${done} of ${esc(c.total)} processed${Number(c.pending)?' · updates every few seconds':''}. Sent means Postmark accepted the message; Delivered and Failed follow from Postmark's delivery reports.</p>`;
document.getElementById('campaign-tabs').innerHTML=campaignOutcomes.map(([s,l,k])=>`<button type="button" class="status-tab${Number(c[k])===0?' is-empty':''}" data-status="${s}" aria-pressed="${status===s}">${l}<span class="status-tab-count">${esc(c[k])}</span></button>`).join('');
document.querySelectorAll('#campaign-tabs .status-tab').forEach(b=>b.addEventListener('click',()=>{status=b.dataset.status;page=1;load().catch(e=>message(e.message,true));}));
document.getElementById('campaign-cancel').hidden=!(Number(c.pending)>0&&!c.cancelled_at);
const pages=Math.max(1,Math.ceil(d.matched/d.page_size));document.getElementById('campaign-recipients').innerHTML=d.recipients.length?`<div class="table-scroll"><table><thead><tr><th scope="col">Email</th><th scope="col">Name</th><th scope="col">Status</th><th scope="col">Attempts</th><th scope="col">Detail</th><th scope="col">Postmark message</th><th scope="col">Updated</th></tr></thead><tbody>${d.recipients.map(r=>`<tr><td>${esc(r.email)}</td><td>${esc(r.name)}</td><td>${esc({queued:'Pending',sending:'Sending',accepted:'Sent'}[r.status]||r.status[0].toUpperCase()+r.status.slice(1))}</td><td>${esc(r.attempts)}</td><td>${esc(r.error_code==='fake_provider'?'':r.error_code)}</td><td class="mono">${esc(r.provider_id)}</td><td>${esc(date(r.updated_at))}</td></tr>`).join('')}</tbody></table></div>${pages>1?`<nav class="actions" aria-label="Recipient pages"><button type="button" class="secondary" id="campaign-prev" ${page<=1?'disabled':''}>Previous</button><span class="help">Page ${page} of ${pages}</span><button type="button" class="secondary" id="campaign-next" ${page>=pages?'disabled':''}>Next</button></nav>`:''}`:'<p class="muted">No recipients match.</p>';
bind('campaign-prev','click',()=>{page--;return load();});bind('campaign-next','click',()=>{page++;return load();});
if(Number(c.pending)>0)campaignTimer=setTimeout(()=>load().catch(()=>{}),4000);};
const d=await api(`/admin/campaigns/${encodeURIComponent(id)}`),cats=(await api('/admin/campaigns')).categories;c=d.campaign;
app.innerHTML=`<div id="campaign-detail" data-id="${esc(id)}"><button id="return" class="secondary">Back to campaigns</button><h1>${esc(c.template_label||c.template_id)}.</h1><div class="card">${pairs([['Status',''],['Subject',c.subject],['Audience',audienceText(c.audience,cats)],['Created',`${date(c.created_at)} by ${c.created_by}`],...(c.cancelled_at?[['Cancelled',`${date(c.cancelled_at)} by ${c.cancelled_by}`]]:[])])}<div id="campaign-progress"></div><div class="actions"><button id="campaign-cancel" class="danger" hidden>Cancel unsent messages</button></div></div><div class="card"><h2>Recipients</h2><div id="campaign-tabs" class="status-tabs" role="group" aria-label="Filter by outcome"></div><label class="admin-search">Search<input id="campaign-search" type="search" placeholder="Email or name" autocomplete="off"></label><div id="campaign-recipients"></div></div></div>`;
document.querySelector('#campaign-detail .review-list dd').id='campaign-state';window.scrollTo({top:0});
bind('return','click',openCampaigns);let typing;document.getElementById('campaign-search').addEventListener('input',e=>{clearTimeout(typing);typing=setTimeout(()=>{search=e.target.value.trim();page=1;load().catch(err=>message(err.message,true));},250);});
bind('campaign-cancel','click',async e=>{if(!confirm('Cancel every message that has not been sent yet? Messages already sent are not affected.'))return;await busy(e.target,async()=>{const r=await post(`/admin/campaigns/${encodeURIComponent(id)}/cancel`,{});message(`${r.cancelled} unsent ${r.cancelled===1?'message':'messages'} cancelled.`);await campaignDetailPage(id);},'Cancelling…');});
await load();}
